<template>
  <section class="operations-dashboard">
    <header class="dashboard-header">
      <div><p class="dashboard-kicker">OPERATIONS CONTROL ROOM</p><h1>平台运行总览</h1><p class="dashboard-subtitle">实时掌握处理服务器、模板与镜像任务的运行状态。</p></div>
      <el-button class="refresh-button" icon="el-icon-refresh" :loading="loading" @click="load">刷新数据</el-button>
    </header>
    <section class="metric-grid" aria-label="平台关键指标">
      <article class="metric-card metric-card-primary"><div class="metric-top"><span>处理服务器</span><i class="el-icon-cpu" /></div><strong>{{ agents.length }}</strong><div class="metric-foot"><span class="status-mark online" />{{ onlineAgents }} 台在线</div><div class="metric-foot muted"><span class="status-mark offline" />{{ agents.length - onlineAgents }} 台离线</div></article>
      <article class="metric-card"><div class="metric-top"><span>容器模板</span><i class="el-icon-box" /></div><strong>{{ enabledTemplates }}</strong><div class="metric-foot">个可用模板</div><div class="metric-foot muted">共 {{ templates.length }} 个版本</div></article>
      <article class="metric-card"><div class="metric-top"><span>镜像资产</span><i class="el-icon-coin" /></div><strong>{{ artifacts.length }}</strong><div class="metric-foot">个目录资产</div><div class="metric-foot muted">{{ readyArtifacts }} 个可发布</div></article>
      <article class="metric-card metric-card-warning"><div class="metric-top"><span>待处理事项</span><i class="el-icon-warning-outline" /></div><strong>{{ issues.length }}</strong><div class="metric-foot">项需要关注</div><div class="metric-foot muted">{{ failedDeployments }} 项推送失败</div></article>
    </section>
    <section class="dashboard-grid">
      <article class="panel health-panel"><header class="panel-header"><div><h2>服务器健康度</h2><p>当前 Agent 心跳与可用性</p></div><router-link to="/operations/processing-agents">查看详情 <i class="el-icon-arrow-right" /></router-link></header><div class="health-content"><div ref="healthChart" class="chart chart-donut" aria-label="服务器在线状态图表" /><div class="health-legend"><div><span class="legend-dot online" /><strong>{{ onlineAgents }}</strong><small>在线</small></div><div><span class="legend-dot offline" /><strong>{{ agents.length - onlineAgents }}</strong><small>离线</small></div><div><span class="legend-dot empty" /><strong>{{ agents.length ? Math.round(onlineAgents / agents.length * 100) : 0 }}%</strong><small>可用率</small></div></div></div></article>
      <article class="panel distribution-panel"><header class="panel-header"><div><h2>资源分布</h2><p>模板与镜像目录规模</p></div><router-link to="/operations/container-templates">管理资源 <i class="el-icon-arrow-right" /></router-link></header><div ref="distributionChart" class="chart chart-bars" aria-label="资源分布图表" /></article>
    </section>
    <section class="dashboard-grid lower-grid">
      <article class="panel issue-panel"><header class="panel-header"><div><h2>运行提醒</h2><p>{{ issues.length ? '需要运维人员关注的状态' : '当前没有待处理事项' }}</p></div><span class="issue-count">{{ issues.length }} 项</span></header><div v-if="issues.length" class="issue-list"><div v-for="(issue, index) in issues.slice(0, 5)" :key="`${issue.type}-${issue.name}-${index}`" class="issue-row"><span class="issue-icon" :class="issue.level"><i :class="issue.level === 'danger' ? 'el-icon-warning-outline' : 'el-icon-time'" /></span><div><strong>{{ issue.name }}</strong><small>{{ issue.type }} · {{ issue.message }}</small></div><el-button type="text" @click="$router.push(issue.route)">处理 <i class="el-icon-arrow-right" /></el-button></div></div><div v-else class="empty-state"><i class="el-icon-circle-check" /><strong>平台运行平稳</strong><span>暂无需要处理的异常或待审批事项</span></div></article>
      <article class="panel quick-panel"><header class="panel-header"><div><h2>运维入口</h2><p>快速进入常用管理模块</p></div></header><nav class="quick-actions"><router-link to="/operations/processing-agents"><i class="el-icon-cpu" /><span><strong>处理服务器</strong><small>心跳、命令与终端</small></span><b class="el-icon-arrow-right" /></router-link><router-link to="/operations/container-templates"><i class="el-icon-box" /><span><strong>容器模板</strong><small>版本与资源配置</small></span><b class="el-icon-arrow-right" /></router-link><router-link to="/operations/image-registry"><i class="el-icon-coin" /><span><strong>镜像仓库</strong><small>上传、审批与推送</small></span><b class="el-icon-arrow-right" /></router-link></nav></article>
    </section>
  </section>
</template>
<script>
import * as echarts from 'echarts'
import { listProcessingAgents } from '@/api/ProcessingAgents'
import { listContainerTemplates } from '@/api/ContainerTemplates'
import { listImageArtifacts, listImageDeployments } from '@/services/imageRegistry'
const value = result => result && result.data !== undefined ? result.data : []
export default {
  name: 'OperationsHome',
  data: () => ({ loading: false, agents: [], templates: [], artifacts: [], deployments: [], healthChart: null, distributionChart: null }),
  computed: {
    onlineAgents () { return this.agents.filter(item => item.online).length },
    enabledTemplates () { return this.templates.filter(item => item.enabled).length },
    readyArtifacts () { return this.artifacts.filter(item => item.importState === 'READY').length },
    failedDeployments () { return this.deployments.filter(item => item.state === 'FAILED').length },
    imageIssues () { return this.artifacts.filter(item => item.reviewState === 'PENDING_REVIEW' || item.importState === 'FAILED').concat(this.deployments.filter(item => item.state === 'FAILED')) },
    issues () { const rows = []; this.agents.filter(item => !item.online).forEach(item => rows.push({ type: '服务器离线', level: 'danger', name: item.displayName || item.hostname || item.agentId, message: 'Agent 心跳中断', route: '/operations/processing-agents' })); this.imageIssues.forEach(item => rows.push({ type: '镜像任务', level: item.failureMessage ? 'danger' : 'warning', name: item.originalFilename || item.targetDigest || item.artifactId, message: item.failureMessage || item.failureCode || '等待审批', route: '/operations/image-registry' })); return rows }
  },
  created () { this.load() },
  beforeDestroy () { window.removeEventListener('resize', this.resizeCharts); if (this.healthChart) this.healthChart.dispose(); if (this.distributionChart) this.distributionChart.dispose() },
  methods: {
    async load () { this.loading = true; try { const [agents, templates, artifacts, deployments] = await Promise.all([listProcessingAgents(), listContainerTemplates(), listImageArtifacts({ limit: 200 }), listImageDeployments({ limit: 200 })]); this.agents = value(agents); this.templates = value(templates); this.artifacts = value(artifacts); this.deployments = value(deployments); this.$nextTick(this.renderCharts) } finally { this.loading = false } },
    resizeCharts () { if (this.healthChart) this.healthChart.resize(); if (this.distributionChart) this.distributionChart.resize() },
    renderCharts () { if (!this.$refs.healthChart || !this.$refs.distributionChart) return; if (!this.healthChart) this.healthChart = echarts.init(this.$refs.healthChart); if (!this.distributionChart) this.distributionChart = echarts.init(this.$refs.distributionChart); this.healthChart.setOption({ animationDuration: 500, tooltip: { trigger: 'item' }, series: [{ type: 'pie', radius: ['64%', '82%'], silent: true, label: { show: false }, data: [{ value: this.onlineAgents, name: '在线', itemStyle: { color: '#2db58a' } }, { value: Math.max(0, this.agents.length - this.onlineAgents), name: '离线', itemStyle: { color: '#e6eaf0' } }] }] }); this.distributionChart.setOption({ animationDuration: 500, grid: { left: 54, right: 22, top: 18, bottom: 28 }, xAxis: { type: 'category', data: ['可用模板', '镜像资产', '待处理'], axisLine: { lineStyle: { color: '#dfe5ec' } }, axisLabel: { color: '#7a8794' } }, yAxis: { type: 'value', minInterval: 1, splitLine: { lineStyle: { color: '#edf1f5' } }, axisLabel: { color: '#9aa5b1' } }, series: [{ type: 'bar', barWidth: 28, data: [{ value: this.enabledTemplates, itemStyle: { color: '#4e7cf4', borderRadius: [5, 5, 0, 0] } }, { value: this.artifacts.length, itemStyle: { color: '#6c9ef8', borderRadius: [5, 5, 0, 0] } }, { value: this.issues.length, itemStyle: { color: '#e6a23c', borderRadius: [5, 5, 0, 0] } }] }] }); window.removeEventListener('resize', this.resizeCharts); window.addEventListener('resize', this.resizeCharts) }
  }
}
</script>
<style scoped>
