ader p{margin:5px 0 0;color:#8a98a5;font-size:12px}.panel-header a{color:#4e7cf4;font-size:12px;text-decoration:none;white-space:nowrap}.chart{height:190px}.health-content{display:grid;grid-template-columns:200px 1fr;align-items:center;min-height:220px;padding:8px 24px}.health-legend{display:grid;gap:16px}.health-legend>div{display:grid;grid-template-columns:10px 46px 1fr;align-items:center;gap:7px}.legend-dot{width:9px;height:9px;margin:0}.legend-dot.empty{background:#e6eaf0}.health-legend strong{color:#253746;font-size:22px}.health-legend small{color:#8794a1;font-size:12px}.chart-bars{height:220px;padding:8px 12px}.issue-count{padding:5px 9px;border-radius:5px;background:#f1f4f8;color:#667582;font-size:12px}.issue-list{padding:6px 20px 10px}.issue-row{display:grid;grid-template-columns:32px 1fr auto;align-items:center;gap:11px;padding:14px 0;border-bottom:1px solid #edf1f5}.issue-row:last-child{border-bottom:0}.issue-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:8px;background:#fff4e2;color:#d28a21}.issue-icon.danger{background:#fff0f0;color:#d75b5b}.issue-row strong,.issue-row small{display:block}.issue-row strong{color:#314758;font-size:13px}.issue-row small{margin-top:4px;color:#8a98a5;font-size:12px}.issue-row .el-button{color:#4e7cf4;font-size:12px}.empty-state{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:220px;color:#91a0ad}.empty-state i{margin-bottom:10px;color:#2db58a;font-size:30px}.empty-state strong{color:#3d5364;font-size:14px}.empty-state span{margin-top:5px;font-size:12px}.quick-actions{padding:4px 20px 9px}.quick-actions a{display:grid;grid-template-columns:34px 1fr 16px;align-items:center;gap:11px;padding:16px 0;border-bottom:1px solid #edf1f5;color:#304656;text-decoration:none}.quick-actions a:last-child{border-bottom:0}.quick-actions i{display:grid;place-items:center;width:32px;height:32px;border-radius:8px;background:#eef3ff;color:#4e7cf4}.quick-actions span{display:grid;gap:4px}.quick-actions strong{font-size:13px}.quick-actions small{color:#8a98a5;font-size:12px}.quick-actions b{color:#a1aeb9;font-size:14px}@media(max-width:1000px){.metric-grid{grid-template-columns:repeat(2,1fr)}.dashboard-grid,.lower-grid{grid-template-columns:1fr}}@media(max-width:560px){.dashboard-header{align-items:stretch;flex-direction:column}.metric-grid{grid-template-columns:1fr}.health-content{grid-template-columns:1fr}.chart-donut{height:170px}.health-legend{grid-template-columns:repeat(3,1fr);gap:5px}.health-legend>div{display:block;text-align:center}.health-legend .legend-dot{display:block;margin:0 auto 6px}.health-legend strong,.health-legend small{display:block}}
</style>
